export function distanceFromPointToLine(
  t: { x: number; y: number },
  p1: { x: number; y: number },
  p2: { x: number; y: number },
) {
  //https://stackoverflow.com/questions/849211/shortest-distance-between-a-point-and-a-line-segment/6853926#6853926
  const A = t.x - p1.x;
  const B = t.y - p1.y;
  const C = p2.x - p1.x;
  const D = p2.y - p1.y;

  const dot = A * C + B * D;
  const len_sq = C * C + D * D;
  let param = -1;
  if (len_sq != 0) {
    param = dot / len_sq;
  } //in case of 0 length line

  let xx, yy;

  if (param < 0) {
    xx = p1.x;
    yy = p1.y;
  } else if (param > 1) {
    xx = p2.x;
    yy = p2.y;
  } else {
    xx = p1.x + param * C;
    yy = p1.y + param * D;
  }

  const dx = t.x - xx;
  const dy = t.y - yy;
  return Math.sqrt(dx * dx + dy * dy);
}

export function formatDistance(d: number) {
  if (!(d > 0)) {
    return '-';
  }
  return d > 1000 ? `${(d / 1000).toFixed(2)}\u202fкм` : `${d.toFixed()}\u2009м`;
}
